class Solution {
  public long maximumScore(int[][] grid) {
    int n = grid.length;
    if (n <= 1) return 0L;
    long[][] columnPrefix = new long[n][n + 1];
    for (int c = 0; c < n; c++) {
      for (int r = 0; r < n; r++) {
        columnPrefix[c][r + 1] = columnPrefix[c][r] + grid[r][c];
      }
    }
    long[] withScore = new long[n + 1];
    long[] withoutScore = new long[n + 1];
    for (int c = 1; c < n; c++) {
      long[] nextWith = new long[n + 1];
      long[] nextWithout = new long[n + 1];
      for (int previousHeight = 0; previousHeight <= n; previousHeight++) {
        long previousColumnScore = 0;
        for (int currentHeight = 0; currentHeight <= n; currentHeight++) {
          if (currentHeight > previousHeight) {
            previousColumnScore += grid[currentHeight - 1][c - 1];
          }
          int clippedHeight = Math.min(previousHeight, currentHeight);
          long currentColumnScore =
              columnPrefix[c][previousHeight] - columnPrefix[c][clippedHeight];
          nextWith[currentHeight] =
              Math.max(
                  nextWith[currentHeight],
                  Math.max(
                      currentColumnScore + withScore[previousHeight],
                      currentColumnScore + previousColumnScore + withoutScore[previousHeight]));
          nextWithout[currentHeight] =
              Math.max(
                  nextWithout[currentHeight],
                  Math.max(
                      withScore[previousHeight],
                      previousColumnScore + withoutScore[previousHeight]));
        }
      }
      withScore = nextWith;
      withoutScore = nextWithout;
    }
    long answer = 0;
    for (long value : withScore) answer = Math.max(answer, value);
    return answer;
  }
}
